from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_keeps_last_record_even_if_its_day_is_earlier():
    events = parse_transcript_log(["a,7,1", "c,2,0", "b,1,1", "a,2,0"])
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_parse_whitespace_comments_and_flag_values():
    assert parse_transcript_log(["", " \t", "  # header", " x , 3 , 0 ", "y, 1,  "]) == [
        {"id": "x", "day": 3, "flagged": False},
        {"id": "y", "day": 1, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,0"])
def test_parse_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "a,1,0", "", bad_line])


def test_daily_counts_include_gaps_and_ignore_out_of_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_trailing_window():
    counts = [2, 3, 1]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 4
    assert flags_in_window(counts, 4) == 6


def test_summary_uses_pooled_rate_and_calendar_days():
    groups = {"a": parse_transcript_log(["a,1,1", "b,5,0"]),
              "b": parse_transcript_log(["c,2,1"]), "empty": []}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"flagged": False}], "c": [{"flagged": True}],
              "b": [{"flagged": True}], "a": []}
    assert top_flagged_groups(groups, 2) == ["b", "c"]
    assert top_flagged_groups(groups, 5) == ["b", "c", "z"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", None), ("b", 1.0), ("c", 1.0), ("z", 0.0)
    ]


def test_longest_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([1, 0, 2, 1, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
